examples:
// Packs a 24-bit unsigned integer value (0-16777215) to only 4 Base64 characters.
string
Int24ToBase64
(
integer
value
)
{
return
llGetSubString
(
llIntegerToBase64
(
value
<<
8
),
0
,
3
);
}
// unpacks a 4-character Base64 value to a 24-bit unsigned integer
integer
Base64ToInt24
(
string
value
)
{
return
(
llBase64ToInteger
(
value
)
>>
8
)
&
0xffffff
;
// Masking required to remove sign extension from bit-shifting
}
